def planar(x,z,seed=None):
 if seed is None:seed=[.7,-1.3,-1.1]
 def full(t):return np.array([0,t[0],np.pi,t[1],0,t[2],np.pi/2])
 R=np.array([[0,1,0],[1,0,0],[0,0,-1]])
 def f(t):
